"""Row-limit boundary: independent residual counting vs driver images."""
import itertools, sys
sys.path.insert(0, '/workspace/tests')
from harness import *

DENY = 4294967295
SVC = [{"name": "A", "label": 1}, {"name": "B", "label": 2}]
LIM = {"images": 16, "cells": 262144, "units": 1024, "contexts": 32768,
       "connections": 4096, "packets": 32768, "files": 8192}

def count_rows(wordset):
    """Minimal complete DFA state count for the finite language wordset (incl. dead)."""
    words = set(wordset)
    # all prefixes
    prefixes = {w[:j] for w in words for j in range(len(w)+1)}
    residuals = {}
    for u in prefixes:
        res = frozenset(w[len(u):] for w in words if w.startswith(u))
        residuals[u] = res
    uniq = set(residuals.values())
    return len(uniq) + 1  # + dead residual (empty set may or may not be present)

def make_policy(wordset):
    return "".join(f"match({','.join(w)}) allow;" for w in sorted(wordset))

def rows_from_driver(wordset):
    r = run_cli(req([job(SVC, [{"op": "stage", "epoch": 1, "policy": make_policy(wordset)}], LIM)]))
    e = r["results"][0]["events"][0]
    if 'image' in e:
        return len(e['image']['rows'])
    return e

# family 1: chain words A^i B, i < n
for n in (2, 5, 100, 360):
    ws = [("A",)*i + ("B",) for i in range(n)]
    expect_rows = count_rows(ws)
    got = rows_from_driver(ws)
    check(f"chain n={n} rows {expect_rows}", got, expect_rows if expect_rows <= 8192 else {"error": "rejected"})

# family 2: binary words of length 12 minus deletions
full = list(itertools.product("AB", repeat=12))
for k in (0, 10, 700):
    ws = full[:-k] if k else full
    expect_rows = count_rows(ws)
    got = rows_from_driver(ws)
    check(f"binary12 minus {k} rows {expect_rows}", got, expect_rows if expect_rows <= 8192 else {"error": "rejected"})

# find exact 8192 / 8193 boundary via deletions from full binary depth-12 (8191 nodes -> minimal)
def rows_for_k(k):
    ws = full[:-k]
    return count_rows(ws)

lo, hi = 0, 4096
target = 8192
# scan for k where rows crosses 8192
best = {}
for k in range(600, 1000, 8):
    best[k] = rows_for_k(k)
cross = [(k, v) for k, v in best.items() if v in (8192, 8193)]
print("   boundary samples:", {k: best[k] for k in sorted(best) if 8190 <= best[k] <= 8195})
for k, v in cross:
    ws = full[:-k]
    got = rows_from_driver(ws)
    want = v if v <= 8192 else {"error": "rejected"}
    check(f"boundary k={k} rows={v}", got, want)
if not cross:
    # at least confirm monotonic consistency around the max
    ks = sorted(best)
    for k in ks:
        ws = full[:-k]
        got = rows_from_driver(ws)
        want = best[k] if best[k] <= 8192 else {"error": "rejected"}
        check(f"binary12 minus {k} rows {best[k]}", got, want)

summary()
EOF
